"""Две истории основателя в одном доступном блоке."""
import re
from pathlib import Path

def combine_stories(html, en=False):
 def t(a,b): return b if en else a
 if en:
  paragraphs=['My wife initially vomited several times over a few hours. Then, within 3–5 minutes, her condition worsened sharply: her limbs cramped, her mouth became numb and breathing became difficult.', 'Doctors later attributed the episode to severe dehydration. At the time, I was frightened and trying to understand what to do. We were outside a major city. When I called the ambulance service, the operator told me to wait for an available crew.', 'While searching our medicine kit, I decided to give her Zyrtec. She began to feel better later, but that sequence does not establish that the medicine caused the improvement. The ambulance arrived about half an hour later and the doctors treated the continuing nausea.', 'That experience became the starting point for SAFEBOX: clear storage and accessible individual instructions, so the whole household knows where to find them.']
 else:
  source=(Path(__file__).parent/'founder-story.html').read_text(encoding='utf-8')
  paragraphs=re.findall(r'<p>(.*?)</p>',source,flags=re.S)
 wife='<p>'+paragraphs[0]+'</p><details class="story-more"><summary>'+t('Читать полностью','Read the full story')+'</summary>'+''.join('<p>'+p+'</p>' for p in paragraphs[1:])+'</details>'
 child=t('<p>Однажды ночью сын внезапно начал сильно кашлять — без остановки. Смотреть на это было страшно. Дома уже были небулайзер и Пульмикорт, которые мы купили за три года до этого по совету врача.</p><p>Я до сих пор думаю: а если бы ничего этого не было под рукой? Этот эпизод, который я описываю как приступ ложного крупа, ещё раз показал мне, почему подготовку нельзя постоянно откладывать.</p><p>Для меня это история о том, чтобы заранее обсудить с врачом нужные средства, знать, где они лежат, и сохранять актуальные назначения рядом с аптечкой.</p>', '<p>One night, my son suddenly began coughing intensely and could not stop. It was frightening to watch. We already had a nebuliser and Pulmicort at home, bought three years earlier on a doctor’s advice.</p><p>I still wonder: what if we had had nothing at hand? This episode, which I describe as croup, reinforced why preparation should not be put off.</p><p>For me, it is a reminder to discuss supplies with a clinician in advance, know where they are and keep current individual instructions accessible.</p>')
 note=t('Личные воспоминания, не инструкция по лечению. Причина улучшения после препарата не установлена. Давняя покупка не подтверждает пригодность лекарства: проверяйте срок годности и следуйте актуальным назначениям врача. При затруднении дыхания нужна экстренная помощь.', 'Personal recollections, not treatment instructions. Improvement after a medicine does not establish its cause. Check expiry dates and follow current medical advice. Breathing difficulty requires urgent medical help.')
 block=f'''<section class="section founder-slider" id="founder-story"><div class="wrap"><div class="eyebrow">{t('Личный опыт основателя','The founder’s personal experience')}</div><h2>{t('История без прикрас','The story, honestly told')}</h2><div class="story-tabs" role="tablist" aria-label="{t('Истории основателя','Founder stories')}"><button id="wife-tab" role="tab" aria-selected="true" aria-controls="wife-panel">{t('История жены','My wife’s story')}</button><button id="child-tab" role="tab" aria-selected="false" aria-controls="child-panel" tabindex="-1">{t('История сына','My son’s story')}</button></div><div class="story-panel" id="wife-panel" role="tabpanel" aria-labelledby="wife-tab"><div class="story-panel-heading"><span class="story-big">{t('3–5 минут','3–5 minutes')}</span><h3>{t('И всё изменилось','And everything changed')}</h3></div>{wife}</div><div class="story-panel" id="child-panel" role="tabpanel" aria-labelledby="child-tab" hidden><div class="story-panel-heading"><span class="story-big">{t('Одна ночь','One night')}</span><h3>{t('Ночной приступ у ребёнка','A child’s sudden nighttime illness')}</h3></div>{child}</div><div class="story-controls"><button class="story-prev" aria-label="{t('Предыдущая история','Previous story')}">←</button><span class="story-counter" aria-live="polite">01 / 02</span><button class="story-next" aria-label="{t('Следующая история','Next story')}">→</button></div><div class="story-takeaway">{t('Так появился SAFEBOX: понятный порядок в аптечке и нужная информация под рукой.','That is how SAFEBOX began: clearly organised supplies and important information within reach.')}</div><p class="story-disclaimer">{note}</p></div></section>'''
 pattern=r'<section class="section (?:honest-story|founder-section)"[^>]*>.*?</section>'
 html,n=re.subn(pattern,lambda m:block,html,count=1,flags=re.S)
 assert n==1,'Founder story not found'
 html=re.sub(r'<section class="section child-story"[^>]*>.*?</section>','',html,flags=re.S)
 prefix='../site/assets/' if en else 'assets/'
 return html+f'<link rel="stylesheet" href="{prefix}story-slider.css"><script src="{prefix}story-slider.js" defer></script>'
